/**
 * TerminalCast — a static terminal transcript, rendered as text.
 * Copy-pastable, no pixels: commands, check lines, and a ruled summary
 * line, in the voice of a real CLI session. Line kinds:
 *   cmd — the prompt line, as typed
 *   ok  — a passed check ("ok  <text>")
 *   dim — de-emphasized filler ("… 13 more checks")
 *   sum — the ruled summary line, with an optional dim note
 */

export type TerminalLine =
  | { kind: "cmd"; text: string }
  | { kind: "ok"; text: string }
  | { kind: "dim"; text: string }
  | { kind: "sum"; text: string; note?: string };

export default function TerminalCast({ lines }: { lines: TerminalLine[] }) {
  return (
    <div className="vterm">
      {lines.map((line, i) => {
        switch (line.kind) {
          case "cmd":
            return (
              <p className="vln vp" key={i}>{line.text}</p>
            );
          case "ok":
            return (
              <p className="vln" key={i}><span className="vok">ok</span>{"  " + line.text}</p>
            );
          case "dim":
            return (
              <p className="vln vdim" key={i}>{line.text}</p>
            );
          case "sum":
            return line.note ? (
              <p className="vln vsum" key={i}>{line.text + " "}<span className="vdim">{line.note}</span></p>
            ) : (
              <p className="vln vsum" key={i}>{line.text}</p>
            );
          default: {
            const exhausted: never = line;
            return exhausted;
          }
        }
      })}
    </div>
  );
}

/* @humanish/terminal-cast — generated from app/globals.css by scripts/extract-registry-css.mjs.
   Do not edit by hand; edit globals.css and run `pnpm registry:build`.
   Assumes a reset that zeroes margins/padding and sets border-box
   (e.g. Tailwind Preflight); the spacing these components depend on is also
   pinned explicitly below. Colors come from the humanish token system
   (@humanish/humanish-tokens); fonts fall back to system stacks unless
   --font-newsreader / --font-geist / --font-geist-mono are provided. */

.vterm { width: 100%; max-width: 560px; font-family: var(--mono); font-size: 12.5px; line-height: 1.95
}

.vln { margin: 0; white-space: pre-wrap; overflow-wrap: anywhere; color: var(--dz-body)
}

.vp { color: var(--dz-ink)
}

.vok { color: var(--accent-dz); font-weight: 500
}

.vdim { color: var(--dz-label)
}

.vsum { color: var(--dz-ink); border-top: 1px solid var(--dz-line); margin-top: 10px; padding-top: 10px
}
